const snippets={"Python": ["from typing import List", "", "class Solution:", "", "    def spiralOrder(self, matrix: List[List[int]]) -> List[int]:", "        (m, n) = (len(matrix), len(matrix[0]))", "        dirs = (0, 1, 0, -1, 0)", "        vis = [[False] * n for _ in range(m)]", "        i = j = k = 0", "        ans = []", "        for _ in range(m * n):", "            ans.append(matrix[i][j])", "            vis[i][j] = True", "            (x, y) = (i + dirs[k], j + dirs[k + 1])", "            if x < 0 or x >= m or y < 0 or (y >= n) or vis[x][y]:", "                k = (k + 1) % 4", "            i += dirs[k]", "            j += dirs[k + 1]", "        return ans"], "Java": ["import java.util.*;", "class Solution {", "    public List<Integer> spiralOrder(int[][] matrix) {", "        int m = matrix.length, n = matrix[0].length;", "        int[] dirs = {0, 1, 0, -1, 0};", "        int i = 0, j = 0, k = 0;", "        List<Integer> ans = new ArrayList<>();", "        boolean[][] vis = new boolean[m][n];", "        for (int h = m * n; h > 0; --h) {", "            ans.add(matrix[i][j]);", "            vis[i][j] = true;", "            int x = i + dirs[k], y = j + dirs[k + 1];", "            if (x < 0 || x >= m || y < 0 || y >= n || vis[x][y]) {", "                k = (k + 1) % 4;", "            }", "            i += dirs[k];", "            j += dirs[k + 1];", "        }", "        return ans;", "    }", "}"]};
